/**
 * Review Routes
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const { authenticate, optionalAuth } = require('../middleware/auth.middleware');
const { Review, Product, User } = require('../models');
const { parsePagination, paginatedResponse } = require('../utils/pagination');

// Get reviews for a product (public)
router.get('/:productId', optionalAuth, async (req, res, next) => {
  try {
    const pagination = parsePagination(req.query);
    const { count: total, rows: reviews } = await Review.findAndCountAll({
      where: { productId: req.params.productId, isApproved: true },
      include: [{ model: User, as: 'user', attributes: ['id', 'name', 'avatar'] }],
      order: [['createdAt', 'DESC']], offset: pagination.offset, limit: pagination.limit,
    });
    res.json({ success: true, ...paginatedResponse(reviews, total, pagination) });
  } catch (error) { next(error); }
});

// Submit a review (authenticated)
router.post('/', authenticate, async (req, res, next) => {
  try {
    const { productId, rating, title, comment } = req.body;
    const review = await Review.create({
      userId: req.userId, productId, rating, title, comment,
    });

    // Update product average rating
    const { fn, col } = require('sequelize');
    const stats = await Review.findOne({
      where: { productId },
      attributes: [
        [fn('AVG', col('rating')), 'avgRating'],
        [fn('COUNT', col('id')), 'reviewCount'],
      ],
      raw: true,
    });
    if (stats) {
      await Product.update({
        avgRating: Math.round(parseFloat(stats.avgRating) * 10) / 10,
        reviewCount: parseInt(stats.reviewCount),
      }, { where: { id: productId } });
    }

    res.status(201).json({ success: true, message: 'Review submitted', data: { review } });
  } catch (error) { next(error); }
});

// Delete own review
router.delete('/:id', authenticate, async (req, res, next) => {
  try {
    await Review.destroy({ where: { id: req.params.id, userId: req.userId } });
    res.json({ success: true, message: 'Review deleted' });
  } catch (error) { next(error); }
});

module.exports = router;
